private TreeNode<T> rotateRight(TreeNode<T> node) {
    if (node == null) {
        return null;
    }
    TreeNode<T> leftChild = node.getLeftChild();
    node.setLeftChild(leftChild.getRightChild());
    leftChild.setRightChild(node);
    node.setParent(leftChild);
    leftChild.setParent(null);
    return leftChild;
}

private TreeNode<T> rotateRight(TreeNode<T> node) {
    if (node == null || node.left == null) {
        throw new IllegalArgumentException("Cannot perform right rotation on a leaf or a single-node node");
    }

    TreeNode<T> newParent = node.left;
    node.left = node.left.right;
    newParent.right = node;
    node.height = Math.max(height(node.left), height(node.right)) + 1;
    newParent.height = Math.max(height(newParent.left), newParent.right) + 1;
    return newParent;
}

private TreeNode<T> rotateRight(TreeNode<T> node) {
    if (node == null || node.getRight() == null) {
        throw new IllegalArgumentException("Node must have a right child for rotation");
    }

    TreeNode<T> temp = node.getRight();
    node.setRight(temp.getLeft());
    temp.setLeft(node);

    return temp;
}

public TreeNode<T> rotateRight(TreeNode<T> node) {
    if (node == null || node.left == null) {
        throw new IllegalArgumentException("Node has not properly initialized left child");
    }

    TreeNode<T> newParent = node.left; // The new parent is the left child of the original node
    TreeNode<T> newLeftChild = newParent.right; // The new left child is the original right child of the new parent
    newParent.right = node; // The new parent becomes the right child of the original node
    node.left = newLeftChild; // The original left child becomes the left child of the new parent
    node.height = calculateHeight(node); // Recalculate the height of the original node
    newParent.height = calculateHeight(newParent); // Recalculate the height of the new parent
    return newParent; // Return the new parent
}

private TreeNode<T> rotateRight(TreeNode<T> node) {
    if (node == null || node.left == null) {
        throw new IllegalArgumentException("Invalid input: node or its left child is null.");
    }

    TreeNode<T> newRoot = node.left;
    node.left = newRoot.right;
    newRoot.right = node;

    return newRoot;
}

