private int parseEndOfLine(string headerPart, int end)
{
    int i;
    for (i = end; i < headerPart.Length; i++)
    {
        if (headerPart[i] == '\r' || headerPart[i] == '\n')
        {
            return i;
        }
    }
    throw new ArgumentException("End of line not found in the provided header part.");
}

private int parseEndOfLine(String headerPart, int end) {
    // Check if the end index is within the bounds of the header part
    if (end >= headerPart.length()) {
        throw new IllegalArgumentException("End index is out of bounds of the header part");
    }

    // Skip the current line until we encounter a \r\n sequence
    while (end <= headerPart.length() - 2 && !headerPart.substring(end, end + 2).equals("\r\n")) {
        end++;
    }

    // Return the index of the \r\n sequence
    return end;
}

private int parseEndOfLine(String headerPart, int end) {
    // Effective end index, which is end + 1 because we need to check behind the character
    int effectiveEnd = end + 1;

    // Search for the \r\n sequence
    int targetIndex = headerPart.indexOf('\r\n', effectiveEnd);

    // If the \r\n sequence is not found, increment the index to check behind the current character
    if (targetIndex == -1) {
        targetIndex = headerPart.indexOf('\r\n', effectiveEnd + 1);
        // If still not found, return -1 indicating the end of line is not found
        if (targetIndex == -1) {
            return -1;
        }
        // Adjust the index to account for the skipping
        return targetIndex - 1;
    }

    // Return the index of the \r\n sequence
    return targetIndex;
}

private int parseEndOfLine(String headerPart, int end) {
    while (end > 0 && headerPart.charAt(end - 1) != '\r' || headerPart.charAt(end - 1) != '\n') {
        end--;
    }
    return end;
}

