@Override
public void write(byte b[]) throws IOException {
    if (b == null) {
        throw new NullPointerException("The input byte array cannot be null");
    }

    int length = b.length;
    if (length <= 0) {
        // If the length is 0, no bytes can be written
        return;
    }

    // Safe write assuming that the length is in the bounds
    int bytesWritten = writeBytes(b, 0, length);
    if (bytesWritten != length) {
        throw new IOException("Failed to write all bytes: actual written bytes was " + bytesWritten);
    }
}

@Override public void write(byte b[]) throws IOException {
    // Invalid input check (e.g., b == null)
    if (b == null) {
        throw new IllegalArgumentException("b cannot be null");
    }

    // Write the length of the byte array to the output stream
    try {
        OutputStream.write(b.length);
    } catch (IOException e) {
        // Handle the exception
        throw new IOException("Error writing the length to the output stream", e);
    }

    // Write each byte of the array to the output stream
    for (byte byteValue : b) {
        try {
            OutputStream.write(byteValue);
        } catch (IOException e) {
            // Handle the exception
            throw new IOException("Error writing byte " + byteValue + " to the output stream", e);
        }
    }
}

