    Map<V, String> vertexIDMap = new HashMap<>();

    // Traverse the graph nodes to assign vertex IDs
    int vertexCount = 0;
    for (V node : target.nodes()) {
        if (!vertexIDMap.containsKey(node)) {
            vertexIDMap.put(node, "V" + vertexCount++);
        }
        resultMap.put(vertexIDMap.get(node), node);
    }

    // Create nodes for the bipartite graph
    Node<V>[] part1Nodes = new Node[vertexIDMap.size()];
    Node<V>[] part2Nodes = new Node[vertexIDMap.size()];

    int part1Index = 0;
    int part2Index = 0;

    for (V vertex : target.nodes()) {
        if (!resultMap.containsValue(vertex)) {
            part1Nodes[part1Index++] = new Node<>(vertex);
            resultMap.put(vertexIDMap.get(vertex), vertex);
        }
    }

    for (V vertex : resultMap.keySet()) {
        if (!resultMap.containsValue(vertex)) {
            part2Nodes[part2Index++] = new Node<>(resultMap.get(vertex));
        }
    }

    // Create edges for the bipartite graph
    for (Node<V> node1 : part1Nodes) {
        for (Node<V> node2 : part2Nodes) {
            target.addEdge(node1, node2);
