    }

    int[] vertexIndex = new int[target.getVertexCount()];
    int[] edgeCount = new int[target.getVertexCount()];
    Random random = new Random();

    // Initialize index for each vertex
    for (int i = 0; i < target.getVertexCount(); i++) {
        vertexIndex[i] = i;
    }

    // Shuffle indices to form a bipartite graph
    shuffle(vertexIndex, random);

    // Create bipartite graph
    for (int i = 0; i < target.getVertexCount(); i++) {
        for (int j = i + 1; j < target.getVertexCount(); j++) {
            int vertexA = vertexIndex[i];
            int vertexB = vertexIndex[j];
            V vertexAResult = resultMap.get(vertexA.toString());
            V vertexBResult = resultMap.get(vertexB.toString());

            if (vertexAResult == null || vertexBResult == null) {
                throw new IllegalStateException("Result map is missing a vertex");
            }

            E edge = target.addEdge(vertexAResult, vertexBResult);
            edgeCount[vertexA]++;

            // Adjust the next vertex index for the other half of the graph
            if (i == j - 1) {
                // The last edge already connects the last non-overlapping pair
                j++;
            } else {
                // Skip the next vertex because it is already used
                j++;
            }
        }
    }

    // Update edge counts and ensure all edges are accounted for
    for (int i = 0; i < target.getVertexCount(); i++) {
        target.setEdgeCount(i, edgeCount[i]);
    }
