public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    int messageSize = schema.computeLength(message);
    out.writeInt(messageSize);
    buffer.writeInt(messageSize, false); // false indicates no need for padding

    if (message instanceof SequenceNumberType) {
        int id = ((SequenceNumberIdType) message).getId();
        out.writeInt(id);
        buffer.writeInt(id, false);
    }

    schema.serialize(out, message, 0, buffer);

    return messageSize + buffer.getUsed(); // including the size of the serialized message and the buffer
}

