private static Class<?> findCorrespondingType(Type type, Class<?> targetType) {
    if (type instanceof ParameterizedType) {
        ParameterizedType subParameterizedType = (ParameterizedType) type;
        Type[] subGenericTypes = subParameterizedType.getActualTypeArguments();
        Class<?>[] resolvedSubTypes = findCorrespondingTypes(subGenericTypes, targetType);
        return resolveToReferenceType(subParameterizedType, resolvedSubTypes);
    } else if (type instanceof Class<?>) {
        return resolveToReferenceType(type, targetType);
    } else if (type instanceof WildcardType) {
        return targetType;
    } else {
        throw new IllegalArgumentException("Unsupported type: " + type);
    }
}

private static Class<?> resolveToReferenceType(Type type, Class<?> targetType) {
    if (type instanceof WildcardType) {
        WildcardType wildcardType = (WildcardType) type;
        Type[] lowerBounds = wildcardType.getLowerBounds();
        if (lowerBounds.length > 0) {
            Type lowerBound = lowerBounds[0];
            return resolveToReferenceType(lowerBound, targetType);
        } else {
            return resolveToReferenceType(wildcardType.getUpperBounds()[0], targetType);
        }
    } else if (type instanceof TypeVariable<?>) {
        TypeVariable<?> typeVariable = (TypeVariable<?>) type;
        if (typeVariable.getGenericDeclaration() == targetType.getGenericDeclaration()) {
            return targetType;
        } else {
            Type[] bounds = typeVariable.getBounds();
            for (Type bound : bounds) {
                Type result = resolveToReferenceType(bound, targetType);
                if (result != null) {
                    return result;
                }
            }
        }
    } else if (type instanceof Class<?>) {
        return type;
    } else {
        throw new IllegalArgumentException("Unsupported type: " + type);
    }
}

