protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> result = new ArrayList<>();

    // Check if the start and end times are valid
    if (start < 0 || end <= start || end > System.currentTimeMillis()) {
        throw new IllegalArgumentException("Invalid time range");
    }

    // Calculate the duration of the data fetch
    long duration = System.currentTimeMillis() - start;
    if (duration < FETCH_DATA_DURATION) {
        result.add(new TimeRange(start, end));
        return result;
    }

    // Split the time range into smaller chunks
    long chunkSize = Math.min(FETCH_DATA_DURATION, duration);
    long remainingTime = duration - chunkSize;
    long nextStart = start + chunkSize;

    while (remainingTime > 0) {
        result.add(new TimeRange(start, nextStart));
        remainingTime -= chunkSize;
        start = nextStart;
        nextStart += chunkSize;
    }

    // Add the final remaining chunk
    result.add(new TimeRange(start, end));

    return result;
}

public static List<TimeRange> buildTimeRanges(long start, long end) {
        if (start < 0 || end < 0 || start >= end) {
            throw new IllegalArgumentException("Start time and end time must be non-negative and start time must be less than end time.");
        }

        if (end - start > FETCH_DATA_DURATION) {
            List<TimeRange> timeRanges = new ArrayList<>();
            while (start < end) {
                TimeRange timeRange = new TimeRange(start, Math.min(start + FETCH_DATA_DURATION - 1, end));
                timeRanges.add(timeRange);
                start = timeRange.getEnd() + 1;
            }
            return timeRanges;
        }

        return new ArrayList<>(List.of(new TimeRange(start, end)));
    }

protected List<TimeRange> buildTimeRanges(long start, long end) {
    if (start < 0 || end < 0) {
        throw new IllegalArgumentException("Start and end times must be non-negative.");
    }
    if (start >= end) {
        throw new IllegalArgumentException("Start time must be less than end time.");
    }
    int fetchDuration = FETCH_DATA_DURATION; // Assuming FETCH_DATA_DURATION is a constant defined somewhere in the codebase
    List<TimeRange> timeRanges = new ArrayList<>();
    // Calculate the number of sub-ranges needed
    int numRanges = (int) Math.ceil((end - start) / (double) fetchDuration);
    // Create and add sub-ranges
    for (int i = 0; i < numRanges; i++) {
        long fromTime = start + i * fetchDuration;
        long toTime = start + (i + 1) * fetchDuration;
        timeRanges.add(new TimeRange(fromTime, toTime, "Data for [" + fromTime + ", " + toTime + ")"));
    }
    return timeRanges;
}

