public static long compressTimeBucket(long timeBucket, int dayStep) {
    if (timeBucket <= 0 || dayStep <= 0) {
        throw new IllegalArgumentException("Time bucket and day step must be positive integers.");
    }
    if (timeBucket % dayStep != 0) {
        throw new IllegalArgumentException("Time bucket must be divisible by day step.");
    }
    return (timeBucket / dayStep) * dayStep;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    if (timeBucket < 0 || dayStep <= 0) {
        throw new IllegalArgumentException("timeBucket must be non-negative and dayStep must be positive!");
    }
    int year = (int) (timeBucket / 10000);
    int month = (int) ((timeBucket % 10000) / 100);
    int day = (int) ((timeBucket % 100) / 10);
    int newDay = day - (day % dayStep);
    int newMonth = ((year * 12) + month - newDay) / dayStep;
    int newYear = ((year * 12) + month - newDay) % dayStep / 12 + 1;
    if (newDay < 1) {
        newMonth--;
        newDay += month * 100;
    }
    if (newMonth < 1) {
        newYear--;
        newMonth += 12;
    }
    return newYear * 10000 + newMonth * 100 + newDay;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    if (timeBucket < 0 || dayStep <= 0) {
        throw new IllegalArgumentException("Invalid input values");
    }

    long startYear = timeBucket / (1000 * 60 * 60 * 24 * 365);
    long startDayInYear = timeBucket % (1000 * 60 * 60 * 24 * 365);
    long startDay = startDayInYear / (1000 * 60 * 60 * 24);
    long startHour = startDayInYear % (1000 * 60 * 60);
    long startMinute = startDayInYear % (1000 * 60);
    long startSecond = startDayInYear % 1000;

    if (dayStep == 1) {
        return timeBucket;
    }

    long compressedTimeBucket = startYear * (1000 * 60 * 60 * 24 * 365) + startDay * (1000 * 60 * 60 * 24) + startHour * 1000 * 60 + startMinute * 1000 + startSecond;

    for (int i = 1; i < dayStep; i++) {
        compressedTimeBucket++;
    }

    return compressedTimeBucket;
}

