    if (timeBucket <= 0 || dayStep <= 0) {
        throw new IllegalArgumentException("Time bucket and day step must be positive.");
    }

    // Calculate the new start time by dividing the time bucket by the day step and rounding down
    long newStartTime = (timeBucket / dayStep) * dayStep;

    return newStartTime;
}

