public static void writeUTF8(CharSequence str, final WriteSession session, final LinkedBuffer lb){
    if (str == null)
        throw new NullPointerException("Input string must not be null.");

    if (session == null)
        throw new NullPointerException("Write session must not be null.");

    if (lb == null)
        throw new NullPointerException("Linked buffer must not be null.");

    int len = str.length();
    for (int i = 0; i < len; i++) {
        session.beginRecord();
        int b1 = getCharCodeAt(str, i), b2;
        if ((b1 & 0xFF80) == 0) {                // 1-byte character (7 bits)
            session.writeInt((b1 << 8) | b2, true);
        } else if ((b1 & 0xFFC0) == 0xC0) {  // 2-byte character (11 bits)
            b2 = getCharCodeAt(str, i + 1);
            session.writeInt(((b1 & 0x1Fu) << 16) | (b2 << 8) | b2, true);
            i++;   // Skip the next character
        } else if ((b1 & 0xFFE0) == 0xE0) {   // 3-byte character (16 bits)
            b2 = getCharCodeAt(str, i + 1);
            b3 = getCharCodeAt(str, i + 2);
            session.writeInt(((b1 & 0x0Fu) << 24) | (b2 << 16) | (b3 << 8) | b3, true);
            i += 2;   // Skip the next two characters
        } else if ((b1 & 0xFFF0) == 0xF0) {  // 4-byte character (21 bits)
            b2 = getCharCodeAt(str, i + 1);
            b3 = getCharCodeAt(str, i + 2);
            b4 = getCharCodeAt(str, i + 3);
            session.writeInt(((b1 & 0x3Fu) << 32) | (b2 << 24) | (b3 << 16) | (b4 << 8) | b4, true);
            i += 3;   // Skip the next three characters
        } else {
            throw new IllegalArgumentException("Invalid UTF-8 sequence at position " + i);
        }
        session.endRecord();
    }

    lb.close();
}

