public static LinkedBuffer writeUTF8(CharSequence str, WriteSession session, LinkedBuffer lb) throws Exception {
    if (str == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    if (session == null) {
        throw new IllegalArgumentException("Write session cannot be null");
    }
    if (lb == null) {
        throw new IllegalArgumentException("LinkedBuffer cannot be null");
    }

    try {
        int len = str.length();
        lb.writerBegin(len);
        for (int i = 0; i < len; i++) {
            int ch = str.charAt(i);
            if (ch > 0x7F) { // UTF-8 multi-byte character
                int remainder = ch;
                for (int j = 0; j < 4; j++) {
                    byte next = (byte)(remainder & 0xff);
                    lb.put(next);
                    remainder >>= 8;
                    if (remainder == 0) break;
                }
            } else {
                lb.put((byte)ch);
            }
        }
        lb.writerEnd();
    } catch (Exception e) {
        lb.writerEnd(); // Ensure the buffer is closed if an error occurs
        throw e;
    }
    return lb;
}

