private static String decodePathSegments(String path, boolean decode) {
    if (!decode) {
        return path;
    }
    char[] chars = path.toCharArray();
    for (int i = 0; i < chars.length; i++) {
        if (chars[i] == '%' && i + 2 < chars.length) {
            char hexChar1 = chars[i + 1];
            char hexChar2 = chars[i + 2];
            if (isHex(hexChar1) && isHex(hexChar2)) {
                int value = parseInt(hexChar1, hexChar2);
                chars[i + 1] = chars[i + 2] = (char) value;
                i += 2; // Skip over the two characters representing the hexadecimal digit
            }
        }
    }
    return new String(chars);
}

