public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> segments = new ArrayList<>();
    String path = u.getPath();

    if (path == null || path.isEmpty()) {
        return segments;
    }

    String delimiter = decode ? URI.THUNK : URI.PATH_PATHDELIM;

    // Trim leading and trailing delimiters
    path = path.startsWith(delimiter) ? path.substring(1) : path;
    path = path.endsWith(delimiter) ? path.substring(0, path.length() - 1) : path;

    // Split the path by delimiters
    String[] pathSegments = path.split(delimiter);

    for (String segment : pathSegments) {
        segments.add(new PathSegmentImpl(decode, segment));
    }

    return segments;
}

