    int count = 0;
    int end = offset + length;

    while (result == 0) {
        if (offset == end) {
            throw new IOException("Incomplete value");
        }
        byte b = buffer[offset++];
        result = b & 0x7F;
        count++;
    }

    while (result >= 0x80) {
        if (offset == end) {
            throw new IOException("Incomplete value");
        }
        byte b = buffer[offset++];
        result = (result << 7) + (b & 0x7F);
        count++;
    }

    value = result;

    if (count > 9) {
        throw new IOException("Value out of range");
    }

    return value;
}

