    if (desiredCapacity < 2) {
        throw new IllegalArgumentException("Capacity must be greater than or equal to 2");
    }

    int candidate = desiredCapacity + 1;

    while(!isPrime(candidate)) {
        candidate++;
        if(candidate > 1000 && desiredCapacity < 1000) {
            candidate += 10; // Additional padding for underflow with numbers > 1000
        }
    }

    return candidate;
}

private static boolean isPrime(int number) {
    if (number <= 1) {
        return false;
    }

    for (int i = 2; i * i <= number; i++) {
        if (number % i == 0) {
            return false;
        }
    }

    return true;
}

public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 2) {
        return 2; // The smallest prime number
    }

    // Starting from the next number above the square root of desiredCapacity
    int primeCandidate = (int) Math.ceil(Math.sqrt(desiredCapacity));

    while (isPrime(primeCandidate) != true) {
        primeCandidate++;
    }

    return primeCandidate;
}

public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 1000) {
        return 1001 + (desiredCapacity - 1000) / 10;
    } else {
        int candidate = desiredCapacity * 2;
        while ( !isPrime(candidate) ) {
            candidate++;
        }
        return candidate;
    }
}

private static boolean isPrime(int candidate) {
    for (int i = 2; i * i <= candidate; i++) {
        if (candidate % i == 0) {
            return false;
        }
    }
    return true;
}

public static int nextPrime(int desiredCapacity) throws IllegalArgumentException {
    if (desiredCapacity <= 0) {
        throw new IllegalArgumentException("Desired capacity must be a positive integer");
    }

    int capacity = desiredCapacity;
    if (desiredCapacity >= 1000) {
        capacity = Math.ceil(constrain(desiredCapacity, 977, 1003));
    }
    if (capacity <= 2) {
        return 3;
    }

    for (int i = 2; i < capacity; i++) {
        if (isPrime(i)) {
            capacity = i;
            break;
        }
    }

    return capacity;
}

private static int constrain(int value, int min, int max) {
    return Math.max(Math.min(value, max), min);
}

private static boolean isPrime(int num) {
    if (num <= 1) return false;
    if (num == 2) return true;
    if (num % 2 == 0) return false;
    int boundary = (int) Math.sqrt(num);

    for (int i = 3; i <= boundary; i += 2) {
        if (num % i == 0) return false;
    }

    return true;
}

