public static Object findFirstMatch(Collection<?> source, Collection<?> candidates) {
    if (source == null || candidates == null) {
        throw new IllegalArgumentException("Parameters must not be null");
    }
    Iterator<?> sourceIterator = source.iterator();
    Iterator<?> candidatesIterator = candidates.iterator();

    while (sourceIterator.hasNext() && candidatesIterator.hasNext()) {
        Object currentSourceElement = sourceIterator.next();
        Object currentCandidateElement = candidatesIterator.next();

        if (currentSourceElement.equals(currentCandidateElement)) {
            return currentSourceElement;
        }
    }

    return null;
}

