    }
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < str.length(); i++) {
        char ch = str.charAt(i);
        switch (ch) {
            case '\'':
                if (i > 0 && str.charAt(i - 1) == '\'') {
                    sb.append(ch);
                } else {
                    sb.append(ch);
                    sb.append(ch);
                }
                break;
            case '\\':
                if (i + 1 < str.length() && str.charAt(i + 1) == 'n') {
                    sb.append('\n');
                    i++;
                } else if (i + 1 < str.length() && str.charAt(i + 1) == 't') {
                    sb.append('\t');
                    i++;
                } else {
                    sb.append(ch);
                    sb.append(ch);
                }
                break;
            default:
