}

public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }

    StringBuilder result = new StringBuilder();
    int i = 0;
    int len = str.length();

    while (i < len) {
        char c = str.charAt(i);

        if (c == '\\') {
            i++;
            if (i >= len) {
                throw new IllegalArgumentException("Incomplete escape sequence: escape character at the end");
            }

            char next = str.charAt(i);
            switch (next) {
                case '\\':
                    result.append('\\');
                    break;
                case 'n':
                    result.append('\n');
                    break;
                case 't':
                    result.append('\t');
                    break;
                case 'b':
                    result.append('\b');
                    break;
                case 'f':
                    result.append('\f');
                    break;
                case 'r':
                    result.append('\r');
                    break;
                default:
                    throw new IllegalArgumentException("Unknown escape sequence: \\{" + next + "}");
            }
        } else {
            result.append(c);
        }

        i++;
    }

    return result.toString();
}

