    if (r == null) {
        throw new IllegalArgumentException("Resource cannot be null");
    }

    Transport transport = r.getTransport();
    if (transport == null) {
        throw new IllegalStateException("Transport cannot be null");
    }

    if (transport.isSuspended()) {
        return Action.CONTINUE;
    }

    // Suspend the resource based on the transport type
    if (transport == Transport.HTTP) {
        // Implement HTTP suspension logic here
        r.suspend();
    } else if (transport == Transport.WEBSOCKET) {
        // Implement WebSocket suspension logic here
        r.suspend();
    } else {
        // Handle other transport types
        throw new IllegalArgumentException("Unsupported transport type " + transport);
    }

    return Action.CONTINUE;
}

public Action inspect(AtmosphereResource r) {
    if (r == null) {
        return Action.RETURN;
    }

    Transport transport = r.getAttribute(AtmosphereResource.TRANSPORT);
    if (transport == null) {
        return Action.CONTINUE;
    }

    if (transport.equals(Transport.SLOW)) {
        try {
            r.pause();
        } catch (InterruptedException e) {
            // Handle interrupt here
        }
        return Action.CONTINUE;
    } else {
        return Action.STOP;
    }
}

