    }
    Enumeration<Appender> enumer = loggers.getAppenders();
    if (enumer == null || !enumer.hasMoreElements()) {
        return 0; // Return 0 if no appenders are attached.
    }
    int count = 0;
    try {
        while (enumer.hasMoreElements()) {
            Appender appender = enumer.nextElement();
            int ret1 = appender.doAppend(event);
            int ret2 = appender.doAppend(event);
            count += Math.max(ret1, ret2); // Update the count with the maximum return value.
        }
    } catch (Exception e) {
        e.printStackTrace(); // Handle any exceptions and print their stack trace.
        return -1; // Return a negative value to indicate failure.
    }
    return count; // Return the total number of appenders that successfully appended the event.
