private String unescapeId(String input) {
    if (input == null) {
        throw new IllegalArgumentException("Input cannot be null");
    }

    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);
        if (c == '\\') {
            if (i + 1 < input.length()) {
                char nextChar = input.charAt(i + 1);
                switch (nextChar) {
                    case '"':
                        sb.append('"');
                        break;
                    case '\\':
                        sb.append('\\');
                        break;
                    case '/':
                        sb.append('/');
                        break;
                    default:
                        throw new IllegalArgumentException("Invalid escape sequence");
                }
                i++; // Skip the next character
            } else {
                throw new IllegalArgumentException("Invalid escape sequence at the end of the string");
            }
        } else {
            sb.append(c);
        }
    }

    return sb.toString();
}

private String unescapeId(String input) {
    if (input == null) {
        throw new IllegalArgumentException("Input cannot be null");
    }
    StringBuilder sb = new StringBuilder();
    int start = 0;
    while (start < input.length()) {
        if (input.charAt(start) == '.') {
            sb.append(input.substring(start, ++start));
        } else {
            sb.append(input.charAt(start));
        }
        start++;
    }
    return sb.toString();
}

private String unescapeId(String input) {
    StringBuilder output = new StringBuilder();
    int length = input.length();
    for (int i = 0; i < length; i++) {
        char c = input.charAt(i);
        if (c == '.') {
            if (i == 0 || input.charAt(i-1) != '\\') {
                output.append("\\.");
            }
        } else {
            output.append(c);
        }
    }
    return output.toString();
}

public String unescapeId(String input) {
    if (input == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    for (char ch : input.toCharArray()) {
        if (ch == '\\') {
            ch = readNextEscape(ch);
        }
        result.append(ch);
    }
    return result.toString();
}

private char readNextEscape(char initial) {
    try {
        return Integer.toChar(Integer.parseInt(Character.toString(initial) + "1", 32));
    } catch (NumberFormatException e) {
        throw new IllegalArgumentException("Invalid escape character: " + initial);
    }
}

private String unescapeId(String input) {
    if (input == null) {
        throw new IllegalArgumentException("Input cannot be null");
    }

    input = input.replaceAll("\\\\.", ".");
    input = input.replaceAll("\\\\_", "_");
    input = input.replaceAll("\\\\s", " ");
    input = input.replaceAll("\\\\t", "\t");
    input = input.replaceAll("\\\\n", "\n");

    return input;
}

