        }

        if (bucketsByLabel.get(minLabel) == null || bucketsByLabel.get(minLabel).isEmpty()) {
            throw new NoSuchElementException("Bucket with label " + minLabel + " is empty");
        }

        // Move all vertices from the bucket with label minLabel to the bucket with label 0
        bucketsByLabel.set(0, new HashSet<>(bucketsByLabel.get(minLabel)));
        bucketsByLabel.set(minLabel, new HashSet<>());

        // Update labels for all vertices after bucket reload
        for (int i = 0; i < bucketsByLabel.size(); i++) {
            if (i == 0) {
                for (Integer vertex : bucketsByLabel.get(0)) {
                    labels.set(vertex, 0);
                }
            } else {
                for (Integer vertex : bucketsByLabel.get(i)) {
                    labels.set(vertex, i);
                }
            }
        }
    } catch (IllegalArgumentException e) {
        System.err.println("Invalid parameter: " + e.getMessage());
    } catch (NoSuchElementException e) {
        System.err.println("No such element: " + e.getMessage());
