private boolean unlink(ListNodeImpl<E> node) {
    if (node == null)
        return true;

    ListNodeImpl<E> prev = node.prev;
    ListNodeImpl<E> next = node.next;

    if (prev != null)
        prev.next = next;

    if (next != null)
        next.prev = prev;

    // reduce the size of the list
    node.index = -1; // Set the element index to -1
    node.data = null; // Clear the element data
    node.prev = null;
    node.next = null;
    node = null;

    return true;
}

