        throw new IllegalArgumentException("node must not be null");
    }

    if (head == node) {
        head = node.next;
        return true;
    }

    ListNodeImpl<E> current = head;
    ListNodeImpl<E> previous = null;

    while (current != null) {
        if (current == node) {
            break;
        }
        previous = current;
        current = current.next;
    }

    if (current == null) {
        return false;
    }

    previous.next = current.next;
    return true;
}

