boolean removeNonNullableNode(ListNodeImpl<E> node) {
    // Check if the node is null
    if (node == null) {
        return false;
    }

    // Check if the node is the head or tail
    if (node == head) {
        head = node.next;
    } else if (node == tail) {
        tail = node.prev;
        tail.next = null;
    } else {
        // Remove the node from the list
        ListNodeImpl<E> prevNode = node.prev;
        ListNodeImpl<E> nextNode = node.next;
        prevNode.next = nextNode;
        nextNode.prev = prevNode;
    }

    return true;
}

public boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        throw new IllegalArgumentException("Node cannot be null");
    }

    ListNodeImpl<E> nextNode = node.getNext();
    if (nextNode != null) {
        nextNode.setPrevious(node.getPrevious());
    }
    if (node.getPrevious() != null) {
        node.getPrevious().setNext(nextNode);
    }

    node.setNext(null);
    node.setPrevious(null);

    return true;
}

