            throw new IllegalArgumentException("Bounds list cannot be null");
        }

        List<Integer> suffixSumList = bounds.stream()
                .mapToObj(index -> {
                    if (index == bounds.size() - 1) {
                        return 0;
                    }
                    return bounds.get(index) + suffixSumList.get(index + 1);
                })
                .collect(Collectors.toList());

        long sum = bounds.stream().collect(Collectors.summingLong(Integer::intValue));

        return new Pair<>(suffixSumList, sum);
    }

