        List<Integer> suffixSumList = new ArrayList<>();
        long allSum = 0;
        for (int i = 0; i < bounds.size(); i++) {
            allSum += bounds.get(i);
            suffixSumList.add(allSum - (i > 0 ? bounds.get(i - 1) : 0));
        }
        return new Pair<>(suffixSumList, allSum);
    }

