    // Handle empty bounds list
    if (bounds == null || bounds.isEmpty()) {
        return new Pair<>(Arrays.asList(), 0L);
    }

    // Initialize the suffix sum)
    List<Integer> suffixSumList = new ArrayList<>(bounds.size());
    long sum = 0;

    // Compute each suffix sum contributed by each element
    for (int i = 0; i < bounds.size(); i++) {
        sum += bounds.get(i);
        suffixSumList.add(sum);
    }

    // Return the computed suffix sum and the sum of all elements
    return new Pair<>(suffixSumList, sum);
}

