    int sizeOfInteger = intValue >= 0 ? 4 : 5;

    // Append the integer to the byte vector
    for (int i = 0; i < sizeOfInteger; i++) {
        byte byteValue = (byte) (intValue >> 8 * (sizeOfInteger - i - 1));
        this.bytes.add(byteValue);
    }

    // Return the byte vector
    return this;
}

public ByteVector putInt(final int intValue) {
    int length = this.size();
    while (length < 4) {
        this.add((byte) 0);
        length++;
    }
    this.ensureCapacity(4);
    this.set(length - 4, (byte) (intValue >> 24));
    this.set(length - 3, (byte) (intValue >> 16));
    this.set(length - 2, (byte) (intValue >> 8));
    this.set(length - 1, (byte) (intValue & 0xff));
    return this;
}

