        throw new IllegalArgumentException(" intValue out of range (0 to 255)");
    }

    byte[] data = new byte[8]; // 8 bytes for 64-bit integer
    int offset = 0;

    // Reverse int to big-endian so we can write it directly into byte array
    for (int i = 7; i >= 0; i--) {
        data[offset++] = (byte) ((intValue >> (i * Integer.BYTES)) & 0xFF);
    }

