public static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (vertices == null || vertices.size() == 0) {
        throw new IllegalArgumentException("Vertices set cannot be null or empty");
    }

    // Check if all vertices in the graph are within the vertices set
    for (V vertex : graph.vertexSet()) {
        if (!vertices.contains(vertex)) {
            throw new IllegalArgumentException("Vertex set contains a vertex not present in the graph");
        }
    }

    // Check if induced subgraph has the same number of vertices as provided
    if (vertices.size() != graph.inducedSubgraph(vertices).vertexSet().size()) {
        return false;
    }

    // Check all pairs of vertices for adjacency
    for (V v : vertices) {
        for (V w : vertices) {
            if (v.equals(w)) continue;

            if (!graph.containsEdge(v, w)) {
                return false;
            }
        }
    }

    return true;
}

