public static String applyRelativePath(String path, String relativePath) {
    try {
        // Check if the path is a full file path with trailing slash
        if (!path.endsWith("/")) {
            path += "/";
        }

        // Check if relativePath is empty
        if (relativePath.isEmpty()) {
            return path;
        }

        // Handle paths with two or more consecutive slashes
        relativePath = relativePath.replaceAll("//+", "/");

        // Concatenate the paths
        return path + relativePath;
    } catch (Exception e) {
        // Handle any potential exceptions
        System.err.println("An error occurred: " + e.getMessage());
        return null;
    }
}

public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null || path.isEmpty() || relativePath.isEmpty()) {
        throw new IllegalArgumentException("Path and relative path cannot be null or empty.");
    }

    // Replace backslashes with forward slashes for consistency
    path = path.replace('\\', '/');
    relativePath = relativePath.replace('\\', '/');

    // Construct the full file path
    String result = path + "/" + relativePath;

    return result;
}

public static String applyRelativePath(String path, String relativePath) {
    // Check for null or empty paths
    if (path == null || path.isEmpty()) {
        throw new IllegalArgumentException("Path cannot be null or empty.");
    }
    if (relativePath == null || relativePath.isEmpty()) {
        return path; // No need to apply if relative path is null
    }

    // Escape special characters in the path
    path = path.replace("\\", "\\\\").replace("\"", "\\\"");
    relativePath = relativePath.replace("\\", "\\\\").replace("\"", "\\\"");

    // Construct the full path
    return path + relativePath;
}

public static String applyRelativePath(String path, String relativePath) {
    // Check if the input path is not null or empty
    if (path == null || path.trim().isEmpty()) {
        throw new IllegalArgumentException("The path cannot be null or empty");
    }

    // Split the path into components
    String[] pathComponents = path.split("/");
    String[] relativePathComponents = relativePath.split("/");

    int i = 0;
    while (i < relativePathComponents.length && i < pathComponents.length) {
        if (relativePathComponents[i].equals("..")) {
            // Go up a level, remove the last component from the path
            if (i > 0) {
                pathComponents = java.util.Arrays.copyOf(pathComponents, pathComponents.length - 1);
            }
        } else {
            // Add the component to the path
            pathComponents = java.util.Arrays.copyOf(pathComponents, pathComponents.length + 1);
            pathComponents[i] = relativePathComponents[i];
        }
        i++;
    }

    // Append any remaining relative path components
    while (i < relativePathComponents.length) {
        pathComponents = java.util.Arrays.copyOf(pathComponents, pathComponents.length + 1);
        pathComponents[i] = relativePathComponents[i];
        i++;
    }

    // Reconstruct the full path
    return java.util.Arrays.stream(pathComponents).filter(s -> !s.isEmpty()).collect(java.util.stream.Collectors.joining("/"));
}

public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Both path and relativePath cannot be null");
    }

    // Check if path is an absolute path
    if (path.startsWith("/")) {
        return path + relativePath;
    }

    // Check if relativePath contains absolute path parts
    String absPath = "/";
    for (String part : relativePath.split("/")) {
        if (part.startsWith("/")) {
            absPath += part;
            continue;
        }
        if (part.isEmpty()) {
            continue;
        }
        absPath += "/" + part;
    }

    return path + absPath;
}

