public static boolean substringMatch(CharSequence str, int index, CharSequence substring) {
    // Handle invalid input
    if (str == null || substring == null || index < 0 || index + substring.length() > str.length()) {
        throw new IllegalArgumentException("Invalid input");
    }

    // Perform substring matching
    for (int i = 0; i < substring.length(); i++) {
        if (str.charAt(index + i) != substring.charAt(i)) {
            return false;
        }
    }
    return true;
}

public static boolean substringMatch(CharSequence str, int index, CharSequence substring) {
    int length = substring.length();
    // Check if the index is within the bounds of the string
    if (index + length > str.length()) {
        return false;
    }
    // Compare the substring with the characters starting at index
    for (int i = 0; i < length; i++) {
        if (!str.charAt(index + i) == substring.charAt(i)) {
            return false;
        }
    }
    return true;
}

public static boolean substringMatch(CharSequence str, int index, CharSequence substring) {
    // Check if the index is within the bounds of the string
    if (index < 0 || index >= str.length()) {
        throw new IllegalArgumentException("Index out of bounds");
    }

    int subIndex = 0;
    for (int i = index; i < str.length() && subIndex < substring.length(); i++) {
        if (str.charAt(i) == substring.charAt(subIndex)) {
            subIndex++;
        } else {
            return false;
        }
    }
    return subIndex == substring.length();
}

public static boolean substringMatch(CharSequence str, int index, CharSequence substring) {
    if (str == null || substring == null) {
        throw new IllegalArgumentException("Input strings cannot be null");
    }
    if (index < 0 || index >= str.length()) {
        throw new IndexOutOfBoundsException("Index is out of bounds for the given string");
    }
    int subLen = substring.length();
    if (subLen == 0) {
        return true; // Empty substring is always considered a match
    }
    for (int i = 0; i < subLen; i++) {
        if (str.charAt(index + i) != substring.charAt(i)) {
            return false;
        }
    }
    return true;
}

public static boolean substringMatch(CharSequence str, int index, CharSequence substring) {
    if (str == null || substring == null || index < 0 || index > str.length() - substring.length()) {
        throw new IllegalArgumentException("Invalid input");
    }
    int endIndex = index + substring.length();
    for (int i = index, j = 0; i < endIndex; i++, j++) {
        if (str.charAt(i) != substring.charAt(j)) {
            return false;
        }
    }
    return true;
}

