    if (event == null) {
        throw new IllegalArgumentException("Logging event cannot be null");
    }

    // Get the logger
    Logger logger = event.getLogger();

    // Check if the logger has any attached appenders
    if (logger.getAppenders() == null || logger.getAppenders().isEmpty()) {
        throw new NullPointerException("Logger has no appenders");
    }

    // Check if the logger has any appenders that are active
    for (Appender appender : logger.getAppenders().values()) {
        if (appender.isActive()) {
            // Append the event to the appender
            appender.doAppend(event);
            // Increment the log count
            if (event.getLogger().getName() != null) {
                EventSource.getSourceCount().logd(World.WORLD_LOG, logger.getName(), "Appended event: " + event.getMessage());
