public synchronized void append(LoggingEvent event) {
    if(event == null || event.getThreadName() == null || event.getMessage() == null) {
        throw new IllegalArgumentException("Log event must not be null and must contain a thread name and a message.");
    }

    try {
        for (Socket socket : clients) {
            PrintWriter out = new PrintWriter(socket.getOutputStream(), true);
            out.println("[" + event.getLogTime().toDate() + "][" + event.getLevel().toString() + "][" + event.getThreadName() + "]" + event.getMessage());
            out.flush();
        }
    } catch (IOException e) {
        logger.error("Error writing log event to clients:", e);
    }
}

